#!/usr/bin/env node

/**
 * Three.js Scene to OBJ Exporter
 * Converts a Three.js scene to Blender-compatible OBJ format (Z-up space)
 * Applies -90 degree X-rotation for coordinate system transformation
 */

const THREE = require('three');
const fs = require('fs');
const path = require('path');

// Import the scene creation function
const { createScene } = require('./data/object.js');

/**
 * Apply -90 degree X-rotation to convert Y-up (Three.js) to Z-up (Blender)
 * Rotation matrix:
 * [1   0   0 ]
 * [0   0   1 ]
 * [0  -1   0 ]
 *
 * Transformation: (x, y, z) → (x, z, -y)
 */
function applyCoordinateTransform(vertex) {
  const temp = vertex.y;
  vertex.y = vertex.z;
  vertex.z = -temp;
  return vertex;
}

/**
 * Collect all meshes and instanced meshes from the scene hierarchy
 */
function collectGeometries(object, geometries = [], updateMatrixWorld = true) {
  if (updateMatrixWorld) {
    object.updateMatrixWorld(true);
  }

  if (object.isMesh) {
    geometries.push({
      type: 'mesh',
      mesh: object,
      geometry: object.geometry,
      worldMatrix: object.matrixWorld.clone(),
      name: object.name
    });
  } else if (object.isInstancedMesh) {
    geometries.push({
      type: 'instancedMesh',
      mesh: object,
      geometry: object.geometry,
      worldMatrix: object.matrixWorld.clone(),
      count: object.count,
      name: object.name
    });
  }

  for (const child of object.children) {
    collectGeometries(child, geometries, false);
  }

  return geometries;
}

/**
 * Convert geometry to vertices and faces
 */
function geometryToVerticesAndFaces(geometry) {
  let vertices = [];
  let faces = [];

  // Get position attribute
  if (!geometry.attributes || !geometry.attributes.position) {
    return { vertices, faces };
  }

  const positions = geometry.attributes.position.array;

  // Extract vertices
  for (let i = 0; i < positions.length; i += 3) {
    vertices.push({
      x: positions[i],
      y: positions[i + 1],
