    for (let i = 0; i < vertices.length; i += 3) {
      faces.push([i, i + 1, i + 2]);
    }
  }

  return { vertices, faces };
}

/**
 * Export single mesh to OBJ content
 */
function exportMesh(mesh, worldMatrix, objState) {
  const { vertices, faces } = geometryToVerticesAndFaces(mesh.geometry);
  let objContent = '';

  // Transform and write vertices
  for (const vertex of vertices) {
    const v = new THREE.Vector3(vertex.x, vertex.y, vertex.z);
    v.applyMatrix4(worldMatrix);
    applyCoordinateTransform(v);

    objContent += `v ${v.x.toFixed(6)} ${v.y.toFixed(6)} ${v.z.toFixed(6)}\n`;
  }

  // Write faces with vertex offset
  for (const face of faces) {
    const a = face[0] + objState.vertexOffset + 1;
    const b = face[1] + objState.vertexOffset + 1;
    const c = face[2] + objState.vertexOffset + 1;
    objContent += `f ${a} ${b} ${c}\n`;
  }

  objState.vertexOffset += vertices.length;
  return objContent;
}

/**
 * Export instanced mesh to OBJ content
 * Each instance is expanded as a separate copy of the geometry
 */
function exportInstancedMesh(instancedMesh, parentWorldMatrix, objState) {
  const geometry = instancedMesh.geometry;
  const { vertices, faces } = geometryToVerticesAndFaces(geometry);
  let objContent = '';

  const instanceMatrix = new THREE.Matrix4();

  for (let instanceIndex = 0; instanceIndex < instancedMesh.count; instanceIndex++) {
    instancedMesh.getMatrixAt(instanceIndex, instanceMatrix);

    // Combine parent world matrix with instance matrix
    const combinedMatrix = parentWorldMatrix.clone().multiply(instanceMatrix);

    // Transform and write vertices for this instance
    for (const vertex of vertices) {
      const v = new THREE.Vector3(vertex.x, vertex.y, vertex.z);
      v.applyMatrix4(combinedMatrix);
      applyCoordinateTransform(v);

      objContent += `v ${v.x.toFixed(6)} ${v.y.toFixed(6)} ${v.z.toFixed(6)}\n`;
    }

    // Write faces with vertex offset
    for (const face of faces) {
      const a = face[0] + objState.vertexOffset + 1;
      const b = face[1] + objState.vertexOffset + 1;
      const c = face[2] + objState.vertexOffset + 1;
      objContent += `f ${a} ${b} ${c}\n`;
    }

    objState.vertexOffset += vertices.length;
  }

  return objContent;
}

/**
 * Main export function
 */
function exportSceneToOBJ(outputPath) {
  console.log('Creating Three.js scene...');
  const scene = createScene();

  console.log('Collecting geometries...');
  const geometries = collectGeometries(scene);
  console.log(`Found ${geometries.length} meshes/instanced meshes`);

  let objContent = '# Exported from Three.js\n';
  objContent += '# Coordinate system: Blender Z-up (after -90° X-rotation)\n\n';

  const objState = { vertexOffset: 0 };

  for (const geom of geometries) {
    console.log(`Exporting: ${geom.name} (${geom.type})`);

    if (geom.type === 'mesh') {
      objContent += exportMesh(geom.mesh, geom.worldMatrix, objState);
    } else if (geom.type === 'instancedMesh') {
      objContent += exportInstancedMesh(
        geom.mesh,
        geom.worldMatrix,
        objState
      );
    }
  }

  // Ensure output directory exists
  const outputDir = path.dirname(outputPath);
  if (!fs.existsSync(outputDir)) {
    fs.mkdirSync(outputDir, { recursive: true });
  }

  // Write to file
  fs.writeFileSync(outputPath, objContent, 'utf8');
  console.log(`\nSuccessfully exported to: ${outputPath}`);
  console.log(`Total vertices: ${objState.vertexOffset}`);
}

// Run export
const outputPath = path.join(__dirname, 'output', 'object.obj');
exportSceneToOBJ(outputPath);

