/**
 * Three.js Scene to OBJ Exporter
 * Converts a Three.js scene to Blender-compatible OBJ format (Z-up space)
 * Applies -90 degree X-rotation for coordinate system transformation
 */

import * as THREE from 'three';
import { writeFileSync, existsSync, mkdirSync } from 'fs';
import { dirname, join } from 'path';
import { fileURLToPath } from 'url';

// Import the scene creation function
import { createScene } from './data/object.js';

const __filename = fileURLToPath(import.meta.url);
const __dirname = dirname(__filename);

/**
 * Apply -90 degree X-rotation to convert Y-up (Three.js) to Z-up (Blender)
 * Rotation matrix:
 * [1   0   0 ]
 * [0   0   1 ]
 * [0  -1   0 ]
 *
 * Transformation: (x, y, z) → (x, z, -y)
 */
function applyCoordinateTransform(vertex) {
  const temp = vertex.y;
  vertex.y = vertex.z;
  vertex.z = -temp;
  return vertex;
}

